# region: fold
def fold(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: gather
def gather(xs, limit=9):
    return [v if v <= limit else limit for v in xs[1:]]

# region: digest
def digest(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: render
def render(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return render(sift(digest(gather(fold(raw)))))

